import React, { useState } from 'react';
import {
  getActiveCompanyCode,
  getApiErrorMessage,
  login,
  logout,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch, useAppSelector } from '../store/hooks';
import styles from './DevPage.module.css';

function readLoginError(err: unknown): string {
  const raw =
    err && typeof err === 'object' && 'message' in err
      ? String((err as { message?: unknown }).message ?? '')
      : '';
  const wrapped = raw ? new Error(raw) : err;
  return getApiErrorMessage(wrapped, 'Tên đăng nhập hoặc mật khẩu không đúng');
}

/** Standalone `/dev` login — `login` thunk (same contract as Mobile `authService.login`). */
export const DevLoginCard: React.FC = () => {
  const dispatch = useAppDispatch();
  const user = useAppSelector((s) => s.auth.user);
  const authed = useAppSelector((s) => s.auth.isAuthenticated);
  const busy = useAppSelector((s) => s.auth.loading || s.auth.logoutLoading);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [message, setMessage] = useState('');
  const [ok, setOk] = useState(false);

  const onSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    if (busy) return;
    const id = username.trim();
    if (!id || !password) {
      setOk(false);
      setMessage('Nhập tài khoản và mật khẩu');
      return;
    }
    setMessage('');
    try {
      const activeCompanyCode = getActiveCompanyCode() || undefined;
      await dispatch(login({ username: id, password, activeCompanyCode })).unwrap();
      setPassword('');
      setOk(true);
      setMessage('Đăng nhập thành công');
    } catch (err) {
      setOk(false);
      setMessage(readLoginError(err));
    }
  };

  const onLogout = () => {
    void dispatch(logout());
    setOk(false);
    setMessage('');
  };

  if (authed && user) {
    const name = user.fullName || user.username;
    return (
      <section className={styles.loginCard} data-feature="dev-login">
        <div className={styles.loginHead}>Đăng nhập</div>
        <p className={styles.loginSession}>
          {name}
          {user.companyCode ? ` · ${user.companyCode}` : ''}
        </p>
        {message ? (
          <p className={ok ? styles.loginOk : styles.loginErr} role="status">{message}</p>
        ) : null}
        <button type="button" className={styles.loginButton} onClick={onLogout} disabled={busy}>
          Đăng xuất
        </button>
      </section>
    );
  }

  return (
    <form className={styles.loginCard} data-feature="dev-login" onSubmit={(e) => void onSubmit(e)}>
      <div className={styles.loginHead}>Đăng nhập</div>
      <label className={styles.loginLabel} htmlFor="dev-login-user">
        Tài khoản
        <input
          id="dev-login-user"
          className={styles.loginInput}
          autoComplete="username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
        />
      </label>
      <label className={styles.loginLabel} htmlFor="dev-login-pass">
        Mật khẩu
        <input
          id="dev-login-pass"
          className={styles.loginInput}
          type="password"
          autoComplete="current-password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
      </label>
      {message ? (
        <p className={ok ? styles.loginOk : styles.loginErr} role="alert">{message}</p>
      ) : null}
      <button type="submit" className={styles.loginButton} disabled={busy}>
        {busy ? 'Đang đăng nhập…' : 'Đăng nhập'}
      </button>
    </form>
  );
};

export default DevLoginCard;
